import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第116章 确实","description":"","frontmatter":{},"headers":[],"relativePath":"第116章_确实.md","filePath":"第116章_确实.md"}'),_={name:"第116章_确实.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第116章-确实" tabindex="-1">第116章 确实 <a class="header-anchor" href="#第116章-确实" aria-label="Permalink to &quot;第116章 确实&quot;">​</a></h1><p>09:38</p><p>她说：我最后一句我要问你。</p><p>我说：你讲。</p><p>她说：你今天要是想留我，你就讲一句留。</p><p>她说：你讲一句我就听。</p><p>她说：我今天早上把话讲成这样，你要留我我就当你有资格留。</p><p>她说：你要是不留，我今天就走了。</p><p>我说：你想听哪一句。</p><p>她说：你自己想。</p><p>09:40</p><p>我坐在那把椅子上。</p><p>我妈那碗粥在我桌上，早就凉了。</p><p>我拿手机打了一行。</p><p>我打的是：你别走。</p><p>我看着那三个字。</p><p>我又打了一行。</p><p>我打的是：我们两个今年再试一次。</p><p>我看着那一句。</p><p>我把这两句一起放在那里。</p><p>我那两分钟里想的不是她。</p><p>我想的是那年冬天那个车站。</p><p>那一年我买了票，我站在检票口前面，我把那张票留在口袋里，我转身走了。</p><p>我这一辈子在那个人生里做过无数件很难的事。</p><p>我今天早上八点十二到九点四十，我一件难事也没做。</p><p>我做的全部是回答。</p><p>她问什么我答什么。</p><p>她要我留我不动。</p><p>我要是想留，我要自己讲。</p><p>我要是不讲，我今天就不是&quot;没留住&quot;。</p><p>我今天就是&quot;没留&quot;。</p><p>09:42</p><p>我把那两句删了。</p><p>我一个字一个字删的。</p><p>我删到&quot;你别走&quot;那三个字剩一个&quot;别&quot;的时候，我停了一下。</p><p>那个&quot;别&quot;我在屏幕上看了三秒。</p><p>然后我把它删干净。</p><p>09:43</p><p>我发出去的是：</p><p>我说：确实。</p><p>我说：你说得对。</p><p>我说：我们两个今年确实该把这个停下来了。</p><p>09:43</p><p>我发完那三个字的时侯，我做了一件今天最不像我的事。</p><p>我拿手机去桌上拿那个本子。</p><p>因为我今天早上八点二十她讲过一句“你数过”，我说我数过。</p><p>她今天讲的是：你查一下。</p><p>我把那个本子从抽屉里拿出来。</p><p>我翻到最后那页有字的地方。</p><p>我数了三十秒。</p><p>我回去拿手机。</p><p>我说：三百七十一句。</p><p>她说：哪三百七十一。</p><p>我说：你讲过的话，我拄下来的。</p><p>她说：拄了多少年。</p><p>我说：十一年。</p><p>她说：那平均一年三十四句。</p><p>我说：对。</p><p>她说：我一年跟你讲了大概几万句，你只拄三十四句。</p><p>我说：我拄的是你讲完以候你自己不认的那一部分。</p><p>她隔了很久。</p><p>09:49</p><p>她说：你这句话我今天不回答。</p><p>我说：为什么。</p><p>她说：因为我今天一回答，我今天早上讲的就不算数了。</p><p>她说：你把这句话收回去。</p><p>我说：我不收。</p><p>她说：你今天不收，你以后每一天都要拿出来看。</p><p>我说：我已经在看。</p><p>她说：你以后不要看。</p><p>我说：为什么。</p><p>她说：因为这句话不是我要的话。</p><p>她说：我要的是你把这个本子烧了。</p><p>她说：我今天不能讲这句，我讲了你要难受到明年。</p><p>我说：那你讲吧。</p><p>她说：我不讲。</p><p>她说：我今年讲不了这句话。</p><p>09:45</p><p>她隔了大概两分钟。</p><p>09:47</p><p>她说：好。</p><p>她说：我今天退。</p><p>她说：我把那个包拆干净。</p><p>她说：我把那个号上的输入法记录清了。</p><p>她说：我这几年没有一天像今天这么轻松。</p><p>她说：我讲这句不是气你。</p><p>她说：我是真的轻松。</p><p>我说：我知道。</p><p>她说：你别难过。</p><p>我说：我不难过。</p><p>她说：你今天要是难过你要讲。</p><p>我说：我今天不讲。</p><p>她说：为什么。</p><p>我说：因为我今天讲了，你明天就要开始照顾我。</p><p>我说：你照顾我你要花三个月。</p><p>我说：我们两个谁也不欠谁，我今天讲的是这个。</p><p>她说：那好。</p><p>09:50</p><p>她说：我最后讲一句。</p><p>我说：你讲。</p><p>她说：我这六年里，你从来没做过一件让我难看的事。</p><p>我说：我也没做过一件让你高兴的事。</p><p>她说：你做过了。</p><p>她说：你把那些话抄下来，抄了一个本子。</p><p>她说：你这个东西我很感激。</p><p>她说：我今天告诉你我感激，是因为我以后不一定有机会讲。</p><p>我说：你为什么以后没机会讲。</p><p>她说：因为我这个人我这辈子不重复我讲过的真话。</p><p>她说：我今天讲了，我就不会再讲。</p><p>她说：你要记住的是&quot;我讲了&quot;，不是&quot;我常讲&quot;。</p><p>我说：我记住了。</p><p>她说：你别记。</p><p>她说：你一记你又要写到一个本子上。</p><p>她说：你写到一个本子上，你就要拿出来看。</p><p>她说：你拿出来看，你就要来找我。</p><p>她说：你今天答应我你不来。</p><p>我说：我不来。</p><p>她说：那你不许记。</p><p>我说：好。</p><p>09:53</p><p>她下线了。</p><p>我拿着手机坐在那把椅子上，看到屏幕上那个时间自己走到九点五十四。</p><p>那一下屋里很安静。</p><p>我妈在外面把那个水龙头开了。</p><p>她那边的上午九点五十三，是这边的下午两点五十三。</p><p>不对。</p><p>是她那边的凌晨，我这边是上午。</p><p>她那边的上午九点五十三。</p><p>我这边下午两点五十三。</p><p>我今天早上八点十二开始，我这边到下午两点五十三。</p><p>我这六个小时里什么都没干。</p><p>我上班迟到了三个钟头。</p><p>我请了半天。</p><p>我妈那天中午问我，你的粥倒了没有。</p><p>我说我喝了。</p><p>她说你怎么这么快。</p><p>我说我热了一下。</p><p>那天上午从她讲&quot;我基本上并不喜欢你&quot;，到她讲&quot;我今天很轻松&quot;，一共五十七分钟。</p><p>我这五十七分钟里删了三次。</p><p>她那边删了零次。</p><p>她今天早上自己删了一句“我今天看见有人卖鸡蛋”。</p><p>她删那句的时侯在三点。</p><p>我这辈子最怕的一件事，是我不敢要。</p><p>我今天早上八点四十四删那一段，我删得比她当年删相册还快。</p><p>她删相册删了八百张不心疼，她说因为她练过。</p><p>我今天早上删一个字删得这么快，我也是练过的。</p><p>我今天早上什么都不要了，我发现我删得比她干净。</p><p>我把那个&quot;别&quot;字删掉的时候，我的手很稳。</p><p>稳到我那天早上坐在那个厨房里，我自己听见了自己手指碰屏幕的声音。</p><p>一下，两下，三下。</p><p>三下就是一个字。</p><p>我那天早上删了一个字，三下。</p>',152)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
